<?php get_header(); ?><main id="primary" class="sd-main"><div class="sd-container sd-content-wrap"><header class="sd-page-header"><div class="sd-breadcrumbs"><?php esc_html_e( 'Search', 'social-discovery' ); ?></div><h1><?php printf( esc_html__( 'Results for “%s”', 'social-discovery' ), esc_html( get_search_query() ) ); ?></h1></header><?php if ( have_posts() ) : ?><div class="sd-grid sd-grid-3"><?php while ( have_posts() ) : the_post(); ?><article class="sd-card sd-card-body"><h2><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h2><p><?php echo esc_html( wp_trim_words( get_the_excerpt(), 24 ) ); ?></p></article><?php endwhile; ?></div><?php the_posts_pagination(); ?><?php else : sd_render_empty( __( 'No results found', 'social-discovery' ), __( 'Try a different search term.', 'social-discovery' ) ); endif; ?></div></main><?php get_footer(); ?>
